mapper.select:
SELECT a.create_time, a.update_time, a.bool_delete_enum, a.id, a.monomer_id, a.area_id, a.product_id, a.product_type, a.old_quantity, a.task_quantity, a.new_quantity, a.change_type, a.artifact_serial_number, a.assemble_serial_number, a.user_id, su.name user_name, a.status, a.type, mba.project_id 'project.id', mba.monomer_id 'monomer.id', mba.area_id 'areaDetail.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'areaDetail.name', mba.serial_number serial_number, a.task_quantity total_task_quantity, a.in_production_quantity total_in_production_quantity ,mba.used_quantity,mba.produced_quantity FROM mes_building_abnormal a LEFT JOIN contract_project cp ON cp.id = a.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN sys_user su ON a.user_id = su.id LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = a.area_id AND pd.bool_delete_enum = FALSE LEFT JOIN tech_machine_part tech_artifact tech_enclosure tech_assemble mba ON mba.id=a.product_id
a.product_type =#{productType}
and id = #{id}
and cp.name like %#{projectName}%
and a.status = #{status}
and a.monomer_id = #{monomerId}
and a.project_id = #{projectId}
and a.area_id = #{areaId}
and mba.serial_number like %#{serialNumber}%
and date(a.create_time) = #{date}
